static void search(int n,int row,int columns,int diag1,int diag2,char boards[][8][9],int*count){int col;int bit;int r;int c;if(row==n){*count=*count+1;return;}for(col=0;col<n;col=col+1){bit=1<<col;if((columns&bit)==0&&(diag1&(1<<(row-col+n-1)))==0&&(diag2&(1<<(row+col)))==0){for(c=0;c<n;c=c+1)boards[*count][row][c]='.';boards[*count][row][col]='Q';boards[*count][row][n]='\0';search(n,row+1,columns|bit,diag1|(1<<(row-col+n-1)),diag2|(1<<(row+col)),boards,count);}}}
int solve_n_queens(int n,char boards[][8][9]){int count;count=0;search(n,0,0,0,0,boards,&count);return count;}
int main(void){char b[16][8][9];int c;c=solve_n_queens(4,b);if(c!=2)return 1;if(b[0][0][1]!='Q'||b[0][1][3]!='Q'||b[0][2][0]!='Q'||b[0][3][2]!='Q')return 2;if(solve_n_queens(1,b)!=1)return 3;return 42;}
